document.addEventListener("DOMContentLoaded",function(){const t=document.querySelector(".hamburger"),e=document.querySelector(".nav-menu");t&&e&&(t.addEventListener("click",function(){e.classList.toggle("open");const n=t.querySelectorAll("span");e.classList.contains("open")?(n[0].style.transform="rotate(45deg) translateY(8px)",n[1].style.opacity="0",n[2].style.transform="rotate(-45deg) translateY(-8px)"):(n[0].style.transform="none",n[1].style.opacity="1",n[2].style.transform="none")}),document.addEventListener("click",function(n){if(!t.contains(n.target)&&!e.contains(n.target)){e.classList.remove("open");const n=t.querySelectorAll("span");n[0].style.transform="none",n[1].style.opacity="1",n[2].style.transform="none"}}));const n=document.querySelector(".site-header");let o=0;window.addEventListener("scroll",function(){const t=window.pageYOffset;t>100?n.classList.add("scrolled"):n.classList.remove("scrolled"),o=t}),document.querySelectorAll('a[href^="#"]').forEach(t=>{t.addEventListener("click",function(t){const e=this.getAttribute("href");if("#"!==e&&""!==e){t.preventDefault();const n=document.querySelector(e);n&&n.scrollIntoView({behavior:"smooth",block:"start"})}})});const s=window.location.pathname.split("/").pop()||"index.html";document.querySelectorAll(".nav-link").forEach(t=>{const e=t.getAttribute("href");(e===s||""===s&&"index.html"===e)&&t.classList.add("active")})});